/**
 * Bundled DCS reference data: countries, unit types, theatres (projection +
 * airfields with parking).
 *
 * Generated by `scripts/gen-reference-data.py` from pydcs, which exports these
 * tables from DCS itself. Loaded lazily — the airfield table is ~900 KB and most
 * sessions never need it.
 */
import { readFileSync } from "node:fs";
import { packagePath } from "../paths.js";

export interface Country {
  id: number;
  name: string;
  short: string;
  /**
   * Unit types the Mission Editor offers this country (DCS's own list, via
   * pydcs). Permissive, not a real-world order of battle: Russia is offered an
   * A-10C. Statics are available to every country and are not listed.
   */
  units: { plane: string[]; helicopter: string[]; ship: string[]; vehicle: string[] };
}

/** One equipment row from a country's Wikipedia list, matched to DCS. */
export interface RealWorldEntry {
  name: string;
  /** Wikipedia article title. */
  wiki: string;
  /**
   * DCS types whose pydcs id/name shares a designation (or, for unnumbered
   * systems, a name) that appears literally in the Wikipedia row. Empty: DCS has
   * no such type.
   */
  dcs: string[];
  /** Of `dcs`, those with the same FULL designation (C-17A = C-17A); the rest are family matches. */
  exact: string[];
  /** Those of `dcs` the Mission Editor offers this country. */
  dcsForCountry: string[];
}

export interface RealWorldCountry {
  pages: Partial<Record<"aircraft" | "ground" | "naval", string>>;
  aircraft: RealWorldEntry[];
  ground: RealWorldEntry[];
  naval: RealWorldEntry[];
}

export interface FlyingType {
  type: string;
  fuelMax: number | null;
  /** Dimensions in metres, used to pick a parking slot the aircraft fits. */
  width: number | null;
  length: number | null;
  height: number | null;
  chaff: number | null;
  flare: number | null;
  tasks: string[];
  defaultTask: string | null;
}

export interface NamedType {
  type: string;
  name: string;
  /** pydcs grouping, e.g. 'AirDefence', 'Armor', 'Fortification', 'Cargo'. */
  group?: string;
}

export interface StaticType extends NamedType {
  shape: string | null;
  /** The `category` field DCS writes on a static unit, e.g. 'Fortifications', 'Cargos'. */
  category: string;
  rate: number;
  canCargo: boolean;
}

export interface UnitTypes {
  plane: FlyingType[];
  helicopter: FlyingType[];
  vehicle: NamedType[];
  ship: NamedType[];
  static: StaticType[];
}

export type UnitCategory = keyof UnitTypes;

export interface Projection {
  centralMeridian: number;
  falseEasting: number;
  falseNorthing: number;
  scaleFactor: number;
}

/** [parking (crossroad index), parking_id (slot name), x, y, flags, width, length, height]. */
export type ParkingSlotTuple = [number, string, number, number, number, number, number, number];

export const SLOT_LARGE = 1;
export const SLOT_HELI = 2;
export const SLOT_AIRPLANES = 4;
export const SLOT_SHELTER = 8;

export interface Airport {
  id: number;
  name: string;
  x: number;
  y: number;
  slots: ParkingSlotTuple[];
}

export interface Theatre {
  projection: Projection;
  airports: Airport[];
}

/**
 * Airfields that do not come from the bundled catalogue — today, airfields sampled from a
 * running DCS into an airbase pack, which is the only source for a theatre pydcs never
 * exported (Iraq, Marianas WWII).
 *
 * It is registered rather than imported so this module keeps knowing nothing about the
 * filesystem layout of packs, and so a theatre's airfields stay bundled-only unless the
 * user actually sampled one. A pack airfield carries `slotsUnverified`, which parking
 * choice reads as "slot dimensions unknown" instead of inventing them.
 */
export interface ExtraAirportSource {
  /** Theatre ids (as DCS writes them in a .miz) this source has airfields for. */
  theatres(): string[];
  airports(theatre: string): (Airport & { slotsUnverified?: boolean; source?: string })[];
}
let extraAirports: ExtraAirportSource | undefined;
export function registerAirportSource(source: ExtraAirportSource | undefined): void {
  extraAirports = source;
}

function load<T>(file: string): T {
  return JSON.parse(readFileSync(packagePath("data", file), "utf8")) as T;
}

let countriesCache: Country[] | undefined;
let unitTypesCache: UnitTypes | undefined;
let theatresCache: Record<string, Theatre> | undefined;
let realWorldCache: { generated: string; countries: Record<string, RealWorldCountry> } | undefined;

/** Real-world inventories from Wikipedia (data/real-world-inventory.json). */
export function realWorldInventory(): { generated: string; countries: Record<string, RealWorldCountry> } {
  return (realWorldCache ??= load<{ generated: string; countries: Record<string, RealWorldCountry> }>(
    "real-world-inventory.json"
  ));
}

/** Does the Mission Editor offer this type to this country? Undefined when unknowable. */
export function countryOffers(countryName: string, type: string): boolean | undefined {
  const c = findCountry(countryName);
  if (!c?.units) return undefined;
  const hit = findUnitType(type);
  if (!hit || hit.category === "static") return undefined;
  return (c.units[hit.category as keyof Country["units"]] ?? []).includes(type);
}

export function countries(): Country[] {
  return (countriesCache ??= load<{ countries: Country[] }>("countries.json").countries);
}

export function unitTypes(): UnitTypes {
  if (!unitTypesCache) {
    // Drop every metadata key (_source, _sha256, ...): only the category arrays are unit types.
    const raw = load<Record<string, unknown>>("unit-types.json");
    const rest = Object.fromEntries(Object.entries(raw).filter(([k]) => !k.startsWith("_"))) as unknown as UnitTypes;
    rest.static = [...rest.static, ...HELIPORT_STATICS];
    unitTypesCache = rest;
  }
  return unitTypesCache;
}

export function theatres(): Record<string, Theatre> {
  return (theatresCache ??= load<{ theatres: Record<string, Theatre> }>("theatres.json").theatres);
}

const normalize = (s: string): string => s.toLowerCase().replace(/[\s_\-.]/g, "");

/** Common names people use for a theatre, mapped to the id DCS writes in the .miz. */
const THEATRE_ALIASES: Record<string, string> = {
  persiangulf: "PersianGulf",
  pg: "PersianGulf",
  sinai: "SinaiMap",
  marianas: "MarianaIslands",
  channel: "TheChannel",
  germany: "GermanyCW",
  coldwargermany: "GermanyCW",
  southatlantic: "Falklands",
};

/** Resolve a theatre name (case/spacing-insensitive, common aliases) to its DCS id. */
export function resolveTheatreName(name: string): string | undefined {
  const key = normalize(name);
  for (const id of Object.keys(theatres())) {
    if (normalize(id) === key) return id;
  }
  return THEATRE_ALIASES[key];
}

export function theatre(name: string): Theatre {
  const id = resolveTheatreName(name);
  const t = id ? theatres()[id] : undefined;
  if (!t) {
    // A theatre with no bundled data is not unusable: missions can be authored on
    // it (the theatre is just a string in the file) and its airfields can come
    // from a pack sampled off a running mission. Only the bundled projection and
    // airfield tables are missing, so say which part is actually unavailable.
    throw new Error(
      `No bundled data for theatre '${name}'. Bundled: ${Object.keys(theatres()).join(", ")}. ` +
        `Placing units and authoring a mission on it still works; what needs bundled data is airfield ` +
        `lookup and lat/lon conversion. For an installed theatre the pinned pydcs does not cover ` +
        `(dcs_install_report lists them), sample its airbases once from a running mission with ` +
        `dcs_airbase_build_pack.`
    );
  }
  return t;
}

/** Find a country by name (case-insensitive) or short code. */
export function findCountry(name: string): Country | undefined {
  const key = normalize(name);
  return countries().find((c) => normalize(c.name) === key || normalize(c.short) === key);
}

export function findCountryById(id: number): Country | undefined {
  return countries().find((c) => c.id === id);
}

/**
 * Heliport statics. pydcs models these in `unit.py` rather than its generated
 * static catalogue, so they are listed here; dcs_miz_add_farp writes them.
 */
const HELIPORT_STATICS: StaticType[] = [
  { type: "FARP", name: "FARP (4 pads)", group: "Heliport", shape: "FARPS", category: "Heliports", rate: 0, canCargo: false },
  { type: "SINGLE_HELIPAD", name: "Single helipad", group: "Heliport", shape: "FARP", category: "Heliports", rate: 0, canCargo: false },
  { type: "Invisible FARP", name: "Invisible FARP", group: "Heliport", shape: "invisiblefarp", category: "Heliports", rate: 0, canCargo: false },
];

/**
 * A source of type ids this data layer does not bundle: mods, DCS types newer
 * than the pinned pydcs, or types learned from the user's own missions. Keeping
 * it behind a registration call leaves `src/data/` filesystem-agnostic.
 */
export interface ExtraTypeSource {
  find(type: string): { category: UnitCategory; entry: NamedType | FlyingType | StaticType } | undefined;
  list(): { type: string; category: UnitCategory }[];
}
let extraTypes: ExtraTypeSource | undefined;
export function registerTypeSource(source: ExtraTypeSource | undefined): void {
  extraTypes = source;
}

/**
 * Find a unit type in any category (exact type id).
 *
 * `source` says where the answer came from. A "learned" entry proves only that
 * the id exists and which category DCS files it under: its catalogue fields are
 * null, so anything needing a maximum fuel, a parking footprint or a task list
 * must treat it as unknown instead of defaulting.
 */
export function findUnitType(
  type: string
): { category: UnitCategory; entry: NamedType | FlyingType | StaticType; source: "bundled" | "learned" } | undefined {
  const heliport = HELIPORT_STATICS.find((h) => h.type === type);
  if (heliport) return { category: "static", entry: heliport, source: "bundled" };
  const all = unitTypes();
  for (const category of Object.keys(all) as UnitCategory[]) {
    const entry = (all[category] as { type: string }[]).find((t) => t.type === type);
    if (entry) return { category, entry: entry as NamedType, source: "bundled" };
  }
  // The bundled catalogue always wins, so a learned entry can never shadow it.
  const extra = extraTypes?.find(type);
  return extra ? { ...extra, source: "learned" } : undefined;
}

/** Type ids an extra source contributes, for listings that say what is placeable. */
export function extraTypeList(): { type: string; category: UnitCategory }[] {
  return extraTypes?.list() ?? [];
}

/** Suggest near matches for a type id that is not in the catalogue. */
export function suggestUnitTypes(type: string, limit = 5): string[] {
  const key = normalize(type);
  const all = unitTypes();
  const hits: string[] = [];
  for (const category of Object.keys(all) as UnitCategory[]) {
    for (const t of all[category] as { type: string; name?: string }[]) {
      if (normalize(t.type).includes(key) || (t.name && normalize(t.name).includes(key))) hits.push(t.type);
    }
  }
  return hits.slice(0, limit);
}

/**
 * Every airfield known for a theatre: the bundled catalogue plus any registered extra
 * source (airbase packs sampled from DCS). A bundled airfield always wins on id, so a
 * sample can never quietly replace pydcs's data.
 */
export function theatreAirports(theatreName: string): {
  theatre: string;
  airports: (Airport & { slotsUnverified?: boolean; source?: string })[];
  source: "bundled" | "pack" | "bundled+pack";
} {
  const id = resolveTheatreName(theatreName);
  const bundled = id ? theatres()[id]?.airports ?? [] : [];
  const extraTheatres = extraAirports?.theatres() ?? [];
  const extraId = id ?? extraTheatres.find((t) => normalize(t) === normalize(theatreName));
  const extra = extraId ? extraAirports?.airports(extraId) ?? [] : [];
  if (!bundled.length && !extra.length) {
    const known = [...new Set([...Object.keys(theatres()), ...extraTheatres])].join(", ");
    throw new Error(
      `Unknown theatre '${theatreName}'. Supported: ${known}.` +
        (extraTheatres.length ? "" : " A theatre with no bundled data needs an airbase pack sampled from a running mission (dcs_airbase_build_pack).")
    );
  }
  const seen = new Set(bundled.map((a) => a.id));
  const airports = [...bundled, ...extra.filter((a) => !seen.has(a.id))];
  return {
    theatre: extraId ?? id ?? theatreName,
    airports,
    source: bundled.length && extra.length ? "bundled+pack" : bundled.length ? "bundled" : "pack",
  };
}

/** Find an airfield on a theatre by id or by name (case/spacing-insensitive, unique prefix ok). */
export function findAirport(theatreName: string, ref: string | number): Airport {
  const t = theatreAirports(theatreName);
  if (typeof ref === "number" || /^\d+$/.test(String(ref))) {
    const id = Number(ref);
    const hit = t.airports.find((a) => a.id === id);
    if (!hit) throw new Error(`No airfield with id ${id} on ${theatreName}.`);
    return hit;
  }
  const key = normalize(String(ref));
  const exact = t.airports.filter((a) => normalize(a.name) === key);
  if (exact.length === 1) return exact[0];
  const partial = t.airports.filter((a) => normalize(a.name).includes(key));
  if (partial.length === 1) return partial[0];
  if (partial.length > 1) {
    throw new Error(
      `Airfield '${ref}' is ambiguous on ${theatreName}: ${partial.slice(0, 8).map((a) => a.name).join(", ")}.`
    );
  }
  throw new Error(`No airfield matching '${ref}' on ${theatreName}. Use dcs_list_airfields to see them.`);
}
